class Solution {
public:
    int countCommas(int n) {
        int ans = 0;
        for (int i = 1; i <= n; i++) {
            int d = 0, x = i;
            while (x) { d++; x /= 10; }
            ans += (d - 1) / 3;
        }
        return ans;
    }
};

