class Solution:
    def countCommas(self, n):
        d = len(str(n))
        ans = 0
        for L in range(4, d):
            ans += 9 * 10 ** (L - 1) * ((L - 1) // 3)
        ans += (n - 10 ** (d - 1) + 1) * ((d - 1) // 3)
        return ans

