class Solution {
    public int countCommas(int n) {
        int d = Integer.toString(n).length();
        long ans = 0;
        for (int L = 4; L < d; L++)
            ans += 9L * pow10(L - 1) * ((L - 1) / 3);
        ans += (long)(n - pow10(d - 1) + 1) * ((d - 1) / 3);
        return (int) ans;
    }
    private long pow10(int e) { long r = 1; while (e-- > 0) r *= 10; return r; }
}

